// M06-T01: every seeded mechanism row loads into the typed registry with a
// def file, ids are unique, and every original a def names is pinned by
// sha256. Expected values come from the seed YAML, docs/plan/counts.json
// (generated by tools/counts.mjs), lineage.json, the originals' SHA256SUMS
// and the original files themselves, never from the defs under test.

import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { parse } from "yaml";
import { z } from "zod";
import { isThrownCommandError, type MechanismDef } from "@hackbuild/spec";
import {
  ADDED_MECHANISMS, MECHANISM_DEFS, MECHANISM_FAMILIES, PACKAGE_VERSION, loadMechanisms, mechanisms, refusedMechanism,
} from "@hackbuild/mechanisms";
import { ORIGINALS_OF_RECORD, originalPath } from "../../../tools/test-support/originals-root.js";

const root = new URL("../../../", import.meta.url);
const read = (p: string): string => readFileSync(new URL(p, root), "utf8");
const sha = (path: string): string => createHash("sha256").update(readFileSync(path)).digest("hex");

/** The seed row shape (seed/mechanisms.seed.yaml); a key outside it refuses the row. */
const seedRow = z.object({
  id: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  family: z.enum(MECHANISM_FAMILIES),
  dof: z.number().int().optional(),
  inputs: z.record(z.string(), z.null()).optional(),
  derived: z.record(z.string(), z.string()).optional(),
  note: z.string().optional(),
  governs: z.array(z.string()).optional(),
  failure_modes: z.array(z.string()).optional(),
  processes: z.array(z.enum(["laser", "fdm"])).optional(),
  provenance: z.string().min(1),
}).strict();
type SeedRow = z.infer<typeof seedRow>;

const seed: SeedRow[] = (parse(read("packages/mechanisms/seed/mechanisms.seed.yaml")) as unknown[]).map((r) => seedRow.parse(r));
interface CanonCount { registered: number; byStatus: Record<string, number>; aliases?: number }
const counts = JSON.parse(read("docs/plan/counts.json")) as { mechanisms: number; archetypes: number; canon: Record<"mechanisms" | "archetypes", CanonCount> };
const defDir = new URL("packages/mechanisms/src/defs/", root);
const tsIn = (dir: URL): string[] => readdirSync(dir).filter((f) => f.endsWith(".ts") && f !== "index.ts").map((f) => f.slice(0, -3));
// The originals canon additions sit in originals/ (M06-T14).
const defFiles = [...tsIn(defDir), ...tsIn(new URL("originals/", defDir))].sort();

interface LineageRow { id: string; kind: "canonical" | "copy"; source: string; sha256: string }
const lineage = JSON.parse(read("lineage.json")) as LineageRow[];

/** A copy of o without key k, so the key is absent rather than undefined. */
const without = <T extends object>(o: T, k: keyof T): Partial<T> => Object.fromEntries(Object.entries(o).filter(([key]) => key !== k)) as Partial<T>;

function thrown(fn: () => unknown): { code: string; path?: string; hint: string; didYouMean?: readonly string[] } {
  try { fn(); } catch (e) {
    if (isThrownCommandError(e)) return e.hbf;
    throw e;
  }
  throw new Error("no error thrown");
}

describe("mechanism registry load", () => {
  test("every seeded id loads with a def file; the seed size is the generated count", () => {
    expect(seed.length).toBe(counts.mechanisms);
    for (const row of seed) {
      expect(defFiles, `seed row ${row.id} has no src/defs/${row.id}.ts`).toContain(row.id);
      expect(mechanisms.get(row.id)?.def.id).toBe(row.id);
    }
    console.log(`mechanisms: ${seed.length} seeded ids load, ${ADDED_MECHANISMS.length} added, ${mechanisms.ids().length} registered`);
  });

  test("def files, the defs index and the registry agree; a def without a seed row is listed in added.ts", () => {
    const seedIds = new Set(seed.map((r) => r.id));
    const added = ADDED_MECHANISMS.map((a) => a.id);
    expect(MECHANISM_DEFS.map((d) => d.id).sort()).toEqual(defFiles);
    expect([...mechanisms.ids()]).toEqual(defFiles);
    for (const id of defFiles) expect(seedIds.has(id) || added.includes(id), `${id} is neither seeded nor in added.ts`).toBe(true);
    for (const id of added) {
      expect(seedIds.has(id), `${id} is seeded and listed as added`).toBe(false);
      expect(defFiles).toContain(id);
    }
  });

  test("ids are unique inside the registry and against the archetype registry", () => {
    const ids = mechanisms.ids();
    expect(new Set(ids).size).toBe(ids.length);
    const archDir = new URL("packages/archetypes/src/defs/", root);
    const archIds = [...tsIn(archDir), ...tsIn(new URL("originals/", archDir))];
    const archSeed = (parse(read("packages/archetypes/seed/archetypes.seed.yaml")) as { id: string }[]).map((r) => r.id);
    expect(archIds.length).toBeGreaterThan(0);
    for (const id of ids) {
      expect(archIds, `${id} is also an archetype id`).not.toContain(id);
      expect(archSeed, `${id} is also an archetype seed id or alias`).not.toContain(id);
    }
    // names.json lands at M16 (never-suggest list); until then uniqueness is checked inside the registries only.
    const names = new URL("registry/names.json", root);
    if (existsSync(names)) {
      const never = JSON.parse(readFileSync(names, "utf8")) as { neverSuggest?: string[] };
      for (const id of ids) expect(never.neverSuggest ?? []).not.toContain(id);
    }
  });

  test("each seeded def carries the seed row's family, dof, governs, failure modes, processes and provenance", () => {
    for (const row of seed) {
      const d = mechanisms.resolve(row.id).def;
      expect(d.family, row.id).toBe(row.family);
      expect(d.dof, row.id).toBe(row.dof ?? null);
      expect([...d.governs], row.id).toEqual(row.governs ?? []);
      expect([...d.failureModes], row.id).toEqual(row.failure_modes ?? []);
      expect([...d.processes], row.id).toEqual(row.processes ?? []);
      expect(d.provenance, row.id).toBe(row.provenance);
    }
  });

  test("every original is pinned: bytes, lineage.json and SHA256SUMS agree; the first is a canonical row", () => {
    let pinned = 0;
    for (const e of mechanisms.entries) {
      const originals = e.def.original ?? [];
      expect(originals.length, `${e.id} names no original`).toBeGreaterThan(0);
      originals.forEach((o, i) => {
        const path = `${ORIGINALS_OF_RECORD}${o.slug}/${o.file}`;
        const local = originalPath(`${o.slug}/${o.file}`);
        expect(existsSync(local), `${e.id} original ${local} is missing`).toBe(true);
        expect(sha(local), `${e.id} ${o.file} bytes`).toBe(o.sha256);
        const rows = lineage.filter((r) => r.source === path);
        expect(rows.length, `${e.id} ${path} has no lineage.json row`).toBeGreaterThan(0);
        for (const r of rows) expect(r.sha256, `lineage ${r.id}`).toBe(o.sha256);
        if (i === 0) expect(rows.some((r) => r.kind === "canonical"), `${e.id} ports from ${path}, which has no canonical row`).toBe(true);
        const sums = readFileSync(originalPath(`${o.slug}/SHA256SUMS`), "utf8").split("\n").find((l) => l.endsWith(`  ${o.file}`));
        expect(sums, `${o.slug}/SHA256SUMS lists ${o.file}`).toBeDefined();
        expect(sums?.slice(0, 64)).toBe(o.sha256);
        pinned++;
      });
    }
    expect(pinned).toBeGreaterThanOrEqual(mechanisms.entries.length);
  });

  test("the generated registry counts in counts.json equal the loaded registry (D-010)", () => {
    const by: Record<string, number> = {};
    for (const e of mechanisms.entries) by[e.def.status] = (by[e.def.status] ?? 0) + 1;
    expect(counts.canon.mechanisms.registered).toBe(mechanisms.ids().length);
    expect(counts.canon.mechanisms.byStatus).toEqual(by);
  });

  test("entries register under the mechanisms kind with a manifest at the package version", () => {
    const pkg = JSON.parse(read("packages/mechanisms/package.json")) as { name: string; version: string };
    expect(PACKAGE_VERSION).toBe(pkg.version);
    for (const e of mechanisms.entries) {
      expect(e.kind).toBe("mechanisms");
      expect(e.version).toBe(e.def.version);
      expect(e.manifest.name).toBe(pkg.name);
      expect(e.manifest.registry).toBe("mechanisms");
      expect(e.manifest.provides).toEqual(mechanisms.ids());
    }
  });
});

describe("refusals", () => {
  test("an unknown id is E_REF with didYouMean", () => {
    const err = thrown(() => mechanisms.resolve("geneva-externl"));
    expect(err.code).toBe("E_REF");
    expect(err.didYouMean).toContain("geneva-external");
  });

  test("a refused entry's derive() and apply() raise E_REF naming its status and reason", () => {
    for (const e of mechanisms.entries) {
      if (e.def.status === "typed") continue;
      const err = thrown(() => e.def.derive({}, undefined as never));
      expect(err.code, e.id).toBe("E_REF");
      expect(err.hint, e.id).toBe(`mechanism ${e.id} is ${e.def.status}: ${e.def.statusReason}`);
      expect(thrown(() => e.def.apply?.(undefined as never)).code).toBe("E_REF");
    }
  });

  const base = refusedMechanism({
    id: "probe-mechanism", family: "logic", dof: 1, governs: [], failureModes: [], processes: ["laser"],
    provenance: "probe", status: "candidate", statusReason: "probe", original: [],
  });
  const refused = (def: unknown): { code: string; path?: string } => thrown(() => loadMechanisms([def as MechanismDef]));

  test("the loader refuses a def that does not type", () => {
    expect(loadMechanisms([base]).ids()).toEqual(["probe-mechanism"]);
    expect(refused({ ...base, family: "gear" })).toMatchObject({ code: "E_SCHEMA", path: "/mechanisms/probe-mechanism/family" });
    expect(refused({ ...base, id: "Probe" })).toMatchObject({ code: "E_SCHEMA", path: "/mechanisms/Probe/id" });
    expect(refused(without(base, "statusReason"))).toMatchObject({ code: "E_SCHEMA", path: "/mechanisms/probe-mechanism/statusReason" });
    expect(refused({ ...without(base, "statusReason"), status: "typed" })).toMatchObject({ code: "E_SCHEMA", path: "/mechanisms/probe-mechanism/reference" });
    expect(refused({ ...base, processes: ["cnc"] })).toMatchObject({ code: "E_SCHEMA", path: "/mechanisms/probe-mechanism/processes/0" });
    expect(refused({ ...base, original: [{ slug: "knurl", file: "files/knurl.html", sha256: "abc", record: "knurl 5.2" }] }))
      .toMatchObject({ code: "E_SCHEMA", path: "/mechanisms/probe-mechanism/original/0/sha256" });
    expect(refused({ ...base, extra: 1 })).toMatchObject({ code: "E_SCHEMA" });
    expect(refused(without(base, "derive"))).toMatchObject({ code: "E_SCHEMA", path: "/mechanisms/probe-mechanism/derive" });
    expect(thrown(() => loadMechanisms([base, base]))).toMatchObject({ code: "E_SCHEMA", path: "/mechanisms/probe-mechanism/id" });
  });
});
